<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ConsentPurpose\Application\Usecase\Create;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Access\ConsentPurpose\Application\Service\Visibility\ConsentPurposeVisibilityService;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ConsentPurpose;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\Gateway\ConsentPurposeWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class ConsentPurposeCreateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly ConsentPurposeVisibilityService $visibility,
        private readonly ConsentPurposeWriteGateway $writer,
    ) {
    }

    public function allowCreate(): Allow
    {
        $this->logDebug("Check allow of create usecase for Consent purpose");
        $span = $this->startSpan("Check allow of create usecase for Consent purpose");
        try {
            $result = $this->dispatcher->dispatch(new ConsentPurposeCreateAllowDecision(Allow::allowed('create', 'Allowed to create by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function create(ConsentPurposeCreateParams $params): ConsentPurposeCreateResult
    {
        $this->logDebug("Run create usecase for Consent purpose");
        $span = $this->startSpan("Run create usecase for Consent purpose");
        try {
            $allow = $this->allowCreate();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to create Consent purpose');
            }
            $this->dispatcher->dispatch(new ConsentPurposeCreateCheck($params));
            $enriched = $this->dispatcher->dispatch(new ConsentPurposeCreateEnrich($params, $params->toAttributes()));
            $attributes = $enriched->getResult();
            $input = $this->visibility->copyWithFixed($attributes);
            $entity = ConsentPurpose::create($input);
            $result = $this->writer->create(
                $entity,
                fn (ConsentPurpose $created) =>
                            $this->visibility->checkVisibility($created)
            );
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new ConsentPurposeCreateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
